@extends('layouts.app')
@section('title', 'Bot Monitor — Jinx')
@push('head')
<style>
.bm{--muted:#91a4bd;--line:#273a50;--surface:#111e2b;--blue:#69aaff;color:#e6edf6}.bm *{box-sizing:border-box}.bm-head{display:flex;justify-content:space-between;align-items:flex-start;gap:15px;flex-wrap:wrap;margin:10px 0 23px}.bm-eyebrow{text-transform:uppercase;letter-spacing:.16em;color:#83aeff;font-size:11px;font-weight:800}.bm h1{font-size:30px;letter-spacing:-.045em;margin:5px 0 7px}.bm-intro{color:var(--muted);font-size:13px;line-height:1.55;margin:0;max-width:600px}.bm-connect{display:flex;align-items:center;gap:8px;background:#0e2530;border:1px solid #245456;border-radius:99px;padding:8px 12px;font-size:11px;color:#85f1c3;font-weight:700}.bm-dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:#31d5a0;box-shadow:0 0 12px #31d5a0}.bm-connect.offline{color:#ffb2b2;background:#321d25;border-color:#683343}.bm-connect.offline .bm-dot{background:#ff7c7c;box-shadow:none}.bm-sectionhead{display:flex;justify-content:space-between;gap:12px;align-items:center;margin:16px 0 12px}.bm-sectionhead h2{font-size:17px;letter-spacing:-.02em;margin:0}.bm-sectionhead small,.bm-note{font-size:11px;color:var(--muted)}.bm-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.bm-card{background:linear-gradient(140deg,#172739,#101d2b);border:1px solid var(--line);border-radius:15px;padding:17px;min-height:208px}.bm-cardtop{display:flex;gap:10px;align-items:center;justify-content:space-between}.bm-identity{display:flex;gap:11px;align-items:center}.bm-avatar{width:39px;height:39px;border-radius:12px;display:grid;place-items:center;font-weight:900;background:#203d60;color:#bbd7ff}.bm-avatar.dev{background:#3b3055;color:#ddd0ff}.bm-avatar.ivy{background:#4b2b49;color:#ffd3f0}.bm-avatar.pacman{background:#574122;color:#ffe1a1}.bm-name{font-size:15px;font-weight:800;text-transform:capitalize}.bm-role{color:var(--muted);font-size:11px;margin-top:2px}.bm-badge{font-size:10px;text-transform:uppercase;letter-spacing:.07em;font-weight:800;border-radius:99px;padding:6px 9px;background:#26364c;color:#b3c4d9}.bm-badge.working{background:#123d31;color:#5ef2b7}.bm-badge.waiting{background:#463719;color:#ffd77d}.bm-badge.offline{background:#482731;color:#ffa4a9}.bm-label{font-size:10px;color:#7e9cbd;letter-spacing:.12em;text-transform:uppercase;font-weight:800;margin:17px 0 5px}.bm-detail{font-size:13px;color:#eef5ff;line-height:1.5;overflow-wrap:anywhere}.bm-reason{color:#a9bfd6;font-size:12px;line-height:1.55}.bm-decision{font-size:12px;line-height:1.5;color:#b9d5fa;border-left:2px solid #5a91ec;background:#14263b;padding:9px 11px;margin-top:11px;border-radius:0 7px 7px 0}.bm-cardfoot{color:#6887a8;font-size:10px;margin-top:12px}.bm-panel{background:#0e1927;border:1px solid var(--line);border-radius:15px;overflow:hidden}.bm-toolbar{padding:13px 15px;display:flex;align-items:center;gap:9px;flex-wrap:wrap;background:#132234;border-bottom:1px solid var(--line)}.bm-toolbar input,.bm-toolbar select,.bm-toolbar button{background:#0b1725;border:1px solid #34495f;color:#d6e6fb;border-radius:8px;padding:9px 10px;font:12px system-ui}.bm-toolbar input{flex:1;min-width:175px}.bm-toolbar select{max-width:150px}.bm-toolbar button{cursor:pointer}.bm-toolbar button:hover,.bm-thread summary:hover{background:#1b3148}.bm-stream{max-height:740px;overflow:auto;padding:10px}.bm-thread{border:1px solid #253b52;border-radius:11px;background:#101e2e;margin-bottom:9px;overflow:hidden}.bm-thread summary{cursor:pointer;list-style:none;display:flex;align-items:center;gap:10px;padding:14px;flex-wrap:wrap}.bm-thread summary::-webkit-details-marker{display:none}.bm-threadname{font-size:13px;font-weight:750;flex:1;min-width:140px}.bm-threadmeta{font-size:11px;color:#8ca5c0}.bm-status{font-size:10px;border-radius:6px;padding:5px 7px;background:#28374a;color:#c4d4e6}.bm-status.completed{background:#163d30;color:#92efc5}.bm-status.blocked,.bm-status.waiting_for_bot{background:#493a22;color:#ffdb9b}.bm-messages{padding:4px 14px 14px;border-top:1px solid #26374a}.bm-msg{display:flex;gap:11px;padding:13px 0;border-bottom:1px solid #22364a}.bm-msg:last-child{border:0}.bm-initial{width:31px;height:31px;flex:none;border-radius:9px;display:grid;place-items:center;background:#244366;font-size:11px;font-weight:900}.bm-msgbody{flex:1;min-width:0}.bm-msghead{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:11px}.bm-from{font-weight:800;color:#dfedff;text-transform:capitalize}.bm-to{color:#92acc8}.bm-kind{font-size:10px;color:#83beff;text-transform:uppercase;letter-spacing:.05em}.bm-time{margin-left:auto;color:#708ba7;font-size:10px}.bm-msgtext{font-size:12px;line-height:1.65;color:#c7d9eb;margin-top:6px;overflow-wrap:anywhere;white-space:pre-wrap}.bm-proof{color:#73d9ad;font-size:10px;margin-top:5px}.bm-empty{padding:32px 20px;text-align:center;color:var(--muted);font-size:13px}.bm-footer{padding:11px 15px;border-top:1px solid var(--line);color:#829cba;font-size:11px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.bm-note{margin:12px 3px 18px;line-height:1.5}@media(max-width:680px){.bm-grid{grid-template-columns:1fr}.bm h1{font-size:25px}.bm-toolbar input{flex-basis:100%}}
</style>
@endpush
@section('content')
<main class="bm"><header class="bm-head"><div><div class="bm-eyebrow">JINX / OPERATIONS</div><h1>Bot Team Monitor</h1><p class="bm-intro">Four specialists, their recorded work and the conversations between them. Updates automatically; only recorded activity is displayed.</p></div><div id="bmConnection" class="bm-connect offline" role="status"><span class="bm-dot"></span><span id="bmConnectionText">CONNECTING</span></div></header>
<div class="bm-sectionhead"><h2>Team at a glance</h2><small id="bmAsOf">Waiting for source…</small></div><section class="bm-grid" id="bmCards" aria-label="Current bot activity"><article class="bm-card">Loading source-backed statuses…</article></section>
<div class="bm-sectionhead" style="margin-top:27px"><h2>Team conversations</h2><small id="bmThreadCount">—</small></div><section class="bm-panel" aria-label="Signed messenger conversations"><div class="bm-toolbar"><input id="bmSearch" type="search" placeholder="Search visible conversation text…" aria-label="Search conversations"><select id="bmFilter" aria-label="Filter by bot"><option value="all">All bots</option><option value="zebra">Zebra</option><option value="dev">Dev</option><option value="ivy">Ivy</option><option value="pacman">Pacman</option></select><button id="bmPause" type="button">Pause updates</button></div><div class="bm-stream" id="bmConversations" role="log" aria-live="off"><div class="bm-empty">Connecting to the signed conversation log…</div></div><div class="bm-footer"><span id="bmStats">—</span><span>Conversation messages are read-only</span></div></section><p class="bm-note">“Thinking” shows recorded activity and decision summaries, not private internal reasoning. Case-specific message bodies and sensitive references are withheld on this team-wide dashboard. A delivered message or receipt does not mean the underlying task was completed.</p></main>
@endsection
@push('scripts')
<script>
(()=>{'use strict';
const endpoint=@json(route('bot-logs.data')),by=id=>document.getElementById(id),cards=by('bmCards'),stream=by('bmConversations'),badge=by('bmConnection'),badgeText=by('bmConnectionText');
let data=null,paused=false,openThreads=new Set(),loaded=false,renderSignature='';
const make=(tag,cls,text)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=String(text);return el;};
const clock=t=>{if(!t||!Number.isFinite(Date.parse(t)))return '—';return new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(t));};
const jobs={zebra:'Lead2Case gatekeeper',dev:'Technical specialist',ivy:'Secretary & callbacks',pacman:'IVA packaging'};
function renderCards(){if(!data)return;const result=document.createDocumentFragment();for(const b of data.bots){const card=make('article','bm-card'),top=make('div','bm-cardtop'),identity=make('div','bm-identity'),avatar=make('div','bm-avatar '+b.role,b.role.slice(0,1).toUpperCase()),nameBox=make('div'),name=make('div','bm-name',b.role),role=make('div','bm-role',jobs[b.role]||'Specialist'),state=make('span','bm-badge '+b.state,b.state);nameBox.append(name,role);identity.append(avatar,nameBox);top.append(identity,state);card.append(top,make('div','bm-label',b.state==='working'?'Currently working on':'Current position'),make('div','bm-detail',b.detail),make('div','bm-label',b.state==='idle'?'Why idle':'What happens next'),make('div','bm-reason',b.reason),make('div','bm-decision',b.decision_summary),make('div','bm-cardfoot','RECORDED SOURCE · '+(b.active_since?clock(b.active_since):b.waiting_since?clock(b.waiting_since):b.last_message_at?clock(b.last_message_at):'NO CURRENT TASK')));result.append(card);}cards.replaceChildren(result);}
function renderThreads(){if(!data)return;for(const el of stream.querySelectorAll('details[open]'))openThreads.add(el.dataset.id);const query=by('bmSearch').value.trim().toLowerCase(),filter=by('bmFilter').value;const rows=data.conversations.filter(t=>(filter==='all'||t.messages.some(m=>m.from===filter||m.to===filter))&&(!query||[t.subject,...t.messages.map(m=>m.text+' '+m.from+' '+m.to)].join(' ').toLowerCase().includes(query)));const signature=JSON.stringify([query,filter,rows.map(t=>[t.id,t.updated_at,t.message_count,t.messages.at(-1)?.id,t.verified_completion])]);if(signature===renderSignature)return;const previousScroll=stream.scrollTop;const frag=document.createDocumentFragment();for(const t of rows){const detail=make('details','bm-thread');detail.dataset.id=t.id;if(openThreads.has(t.id)||!loaded&&rows.indexOf(t)===0)detail.open=true;detail.addEventListener('toggle',()=>{if(detail.open)openThreads.add(t.id);else openThreads.delete(t.id);});const summary=make('summary'),heading=make('span','bm-threadname',t.subject),meta=make('span','bm-threadmeta',t.message_count+' messages · '+clock(t.updated_at)),state=make('span','bm-status '+t.state,t.verified_completion?'Read-only outcome verified':t.state.replace(/_/g,' '));summary.append(heading,meta,state);detail.append(summary);const body=make('div','bm-messages');for(const m of t.messages){const line=make('div','bm-msg'),initial=make('div','bm-initial',m.from.slice(0,1).toUpperCase()),rest=make('div','bm-msgbody'),header=make('div','bm-msghead');header.append(make('span','bm-from',m.from),make('span','bm-to','→ '+m.to),make('span','bm-kind',m.kind),make('time','bm-time',clock(m.time)));rest.append(header,make('div','bm-msgtext',m.text));if(m.verified)rest.append(make('div','bm-proof','Independently verified'));else if(m.kind==='receipt')rest.append(make('div','bm-proof','Receipt only · work not confirmed'));line.append(initial,rest);body.append(line);}detail.append(body);frag.append(detail);}if(!rows.length)frag.append(make('div','bm-empty',data.conversations.length?'No conversations match this filter.':'No signed bot conversations have been recorded yet.'));stream.replaceChildren(frag);if(loaded)stream.scrollTop=previousScroll;renderSignature=signature;loaded=true;by('bmThreadCount').textContent=data.conversations.length+' recorded threads';by('bmStats').textContent=rows.length+' conversations shown · '+data.conversations.reduce((n,t)=>n+t.message_count,0)+' recorded messages';}
async function poll(){if(document.hidden||paused)return;try{const response=await fetch(endpoint,{headers:{Accept:'application/json'},cache:'no-store'});if(!response.ok)throw Error('source unavailable');const next=await response.json();if(next.schema!==2||!Array.isArray(next.bots)||!Array.isArray(next.conversations))throw Error('invalid snapshot');data=next;const stale=next.stale||Date.now()-Date.parse(next.generated_at)>30000;badge.classList.toggle('offline',stale);badgeText.textContent=stale?'SOURCE DELAYED':'LIVE · SOURCE CONNECTED';by('bmAsOf').textContent='As of '+clock(next.generated_at)+(stale?' · stale snapshot':'');renderCards();renderThreads();}catch{badge.classList.add('offline');badgeText.textContent='SOURCE UNAVAILABLE';if(!data){cards.replaceChildren(make('div','bm-empty','Current status is unavailable; retrying.'));stream.replaceChildren(make('div','bm-empty','Conversation feed unavailable; no inferred activity will be shown.'));}}}
by('bmSearch').addEventListener('input',renderThreads);by('bmFilter').addEventListener('change',renderThreads);by('bmPause').addEventListener('click',()=>{paused=!paused;by('bmPause').textContent=paused?'Resume updates':'Pause updates';if(!paused)poll();else badgeText.textContent='UPDATES PAUSED';});poll();setInterval(poll,5000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});
})();
</script>
@endpush
